  common_pool_diagnostic={'models':['F6_SINGLE_MLP','F7_RIDGE','F8_TREE'],'pool':'F0 full30k, only rescore and primary25/0/15/10/10; no generation or UE','execution':'post-freeze later analysis; not yet run'},
